//! Non-empty paths of asymmetric lenses.
//!
//! A [`LensPath`] is the free-category morphism generated by atomic
//! [`Lens`] stages. Composition concatenates those stages and never changes
//! them. Each instance shape derives its own deterministic normal form for
//! execution; this module provides the tree normal form and its get and put
//! folds.

use std::ops::Range;

use panproto_inst::identity::{
    ComplementShape, IdentityCarrier, IdentityEnvelope, IdentityField, IdentityPolicy,
    IdentityStatus,
};
use panproto_inst::{
    BoundaryProtocols, CompiledMigration, Digest, FInstance, GInstance, GraphComplement,
    PutDomainError, TableComplement, WInstance,
};
use panproto_schema::{Protocol, Schema};
use serde::{Deserialize, Serialize};

use crate::asymmetric;
use crate::compose::{check_boundary, duplicate, tree_fusion};
use crate::graph_lens::{self, graph_fusion};
use crate::table_lens::{self, table_fusion};
use crate::{Complement, Lens, LensError};

/// One group in a shape-specific normal form of a [`LensPath`].
#[derive(Debug)]
pub struct NormalGroup {
    /// The contiguous atomic-stage range represented by `lens`.
    pub stages: Range<usize>,
    /// The fused lens, or the atomic lens for a one-stage group.
    pub lens: Lens,
}

/// The location of an error in a path's normal form.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct StageIndex {
    /// Zero-based normal-form group index.
    pub group: usize,
    /// Contiguous atomic-stage range covered by the group.
    pub stages: Range<usize>,
}

/// The complement a normal-form group's get records.
///
/// A group of several atomic stages runs as its fused lens when every
/// anchor and edge label of its source is declared by the group's source
/// schema, and as its atomic stages in sequence otherwise. The two forms
/// keep the group observationally equal to its stages: on a declared source
/// the first stage of a fused pair leaves no residue, while an undeclared
/// anchor or label would make it drop or refuse what the fused lens cannot
/// attribute to that stage.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GroupComplement<C> {
    /// The complement of the group's lens, fused or atomic.
    Fused(C),
    /// One complement per atomic stage of the group, in forward order.
    Sequential(Vec<C>),
}

impl<C> GroupComplement<C> {
    /// The recorded complements in forward order: the one complement of a
    /// fused form, or one per atomic stage of a sequential form.
    #[must_use]
    pub fn complements(&self) -> &[C] {
        match self {
            Self::Fused(complement) => std::slice::from_ref(complement),
            Self::Sequential(complements) => complements,
        }
    }
}

/// One complement entry produced by a normal-form group.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PathComplementEntry<C> {
    /// The complement produced by the group's get.
    pub complement: GroupComplement<C>,
    /// The identity envelope of the fused group lens.
    pub envelope: IdentityEnvelope,
    /// Lens digests of the atomic stages covered by the group, in order.
    pub stage_digests: Vec<Digest>,
}

/// Complements produced by a lens path, one per normal-form group.
///
/// The wire form is the sequence of entries itself rather than an object
/// containing a named `entries` field.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(transparent)]
pub struct PathComplement<C>(Vec<PathComplementEntry<C>>);

impl<C> PathComplement<C> {
    /// Construct a path complement from its group entries.
    #[must_use]
    pub const fn new(entries: Vec<PathComplementEntry<C>>) -> Self {
        Self(entries)
    }

    /// Group entries in forward execution order.
    #[must_use]
    pub fn entries(&self) -> &[PathComplementEntry<C>] {
        &self.0
    }

    /// Number of normal-form group entries.
    #[must_use]
    pub fn len(&self) -> usize {
        self.0.len()
    }

    /// Whether this complement has no group entries.
    ///
    /// A complement produced by a valid path is never empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
}

/// A non-empty sequence of atomic lenses.
#[derive(Debug)]
pub struct LensPath {
    stages: Vec<Lens>,
    distinguished_identity: bool,
}

impl LensPath {
    /// A one-stage path containing `lens` as an atomic stage.
    ///
    /// This does not recognize an identity-shaped lens as the distinguished
    /// categorical identity; only [`LensPath::identity`] sets that marker.
    #[must_use]
    pub fn single(lens: Lens) -> Self {
        Self {
            stages: vec![lens],
            distinguished_identity: false,
        }
    }

    /// The distinguished identity path at `schema`.
    #[must_use]
    pub fn identity(schema: &Schema) -> Self {
        let compiled = CompiledMigration {
            surviving_verts: schema.vertices.keys().cloned().collect(),
            surviving_edges: schema.edges.keys().cloned().collect(),
            ..CompiledMigration::default()
        };
        Self {
            stages: vec![Lens {
                compiled,
                src_schema: schema.clone(),
                tgt_schema: schema.clone(),
            }],
            distinguished_identity: true,
        }
    }

    /// Atomic stages, in execution order.
    #[must_use]
    pub fn stages(&self) -> &[Lens] {
        &self.stages
    }

    /// Number of atomic stages.
    #[must_use]
    pub fn len(&self) -> usize {
        self.stages.len()
    }

    /// Whether this path has no atomic stages.
    ///
    /// A `LensPath` is non-empty, so this always returns `false`.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        false
    }

    /// Source schema of the first atomic stage.
    #[must_use]
    pub fn src_schema(&self) -> &Schema {
        &self.stages[0].src_schema
    }

    /// Target schema of the last atomic stage.
    #[must_use]
    pub fn tgt_schema(&self) -> &Schema {
        &self.stages[self.stages.len() - 1].tgt_schema
    }

    /// Whether this is the identity path constructed by
    /// [`LensPath::identity`].
    #[must_use]
    pub const fn is_identity(&self) -> bool {
        self.distinguished_identity
    }

    /// Compose this path with `next`.
    ///
    /// Composition checks the shared boundary and otherwise concatenates
    /// the atomic stages. It never performs a shape-specific fusion.
    ///
    /// # Errors
    ///
    /// [`LensError::CompositionMismatch`] when the target schema of this
    /// path differs from the source schema of `next`.
    pub fn then(&self, next: &Self) -> Result<Self, LensError> {
        check_boundary(self.tgt_schema(), next.src_schema())?;
        if self.distinguished_identity {
            return Ok(next.duplicate());
        }
        if next.distinguished_identity {
            return Ok(self.duplicate());
        }
        let stages = self
            .stages
            .iter()
            .chain(&next.stages)
            .map(duplicate)
            .collect();
        Ok(Self {
            stages,
            distinguished_identity: false,
        })
    }

    /// Identity envelopes of the atomic stages, in order.
    #[must_use]
    pub fn identity_envelope(&self, shape: ComplementShape) -> Vec<IdentityEnvelope> {
        self.stages
            .iter()
            .map(|stage| stage.identity(shape))
            .collect()
    }

    /// Deterministic tree normal form for the leftmost-first fusion strategy.
    ///
    /// Starting from one group per atomic stage, this repeatedly fuses the
    /// leftmost adjacent pair admitted by the tree fusion predicate until
    /// no adjacent pair is admitted. The result is a function of the atomic
    /// stages. It is neither a canonical form of lens behaviour nor
    /// necessarily minimal in the number of groups.
    #[must_use]
    pub fn tree_normal_form(&self) -> Vec<NormalGroup> {
        let mut groups: Vec<NormalGroup> = self
            .stages
            .iter()
            .enumerate()
            .map(|(index, lens)| NormalGroup {
                stages: index..index + 1,
                lens: duplicate(lens),
            })
            .collect();
        loop {
            let Some((index, fused)) = groups.windows(2).enumerate().find_map(|(index, pair)| {
                tree_fusion(&pair[0].lens, &pair[1].lens).map(|lens| (index, lens))
            }) else {
                break;
            };
            let stages = groups[index].stages.start..groups[index + 1].stages.end;
            groups.splice(
                index..=index + 1,
                [NormalGroup {
                    stages,
                    lens: fused,
                }],
            );
        }
        groups
    }

    /// Deterministic graph normal form for the leftmost-first fusion strategy.
    ///
    /// Starting with the atomic stages, repeatedly fuses the leftmost
    /// adjacent pair admitted by the graph fusion predicate. The result is a
    /// function of the atomic stages, not a canonical form of graph-lens
    /// behaviour, and it need not use the fewest possible groups. Reading the
    /// rightmost failing group as Kleisli composition of partial puts in the
    /// error monad, and one complement entry per group as its product
    /// complement, is inferred from `xie2025effectful`, Sections 2.1 and 2.4.
    #[must_use]
    pub fn graph_normal_form(&self) -> Vec<NormalGroup> {
        let mut groups: Vec<NormalGroup> = self
            .stages
            .iter()
            .enumerate()
            .map(|(index, lens)| NormalGroup {
                stages: index..index + 1,
                lens: duplicate(lens),
            })
            .collect();
        loop {
            let Some((index, fused)) = groups.windows(2).enumerate().find_map(|(index, pair)| {
                graph_fusion(&pair[0].lens, &pair[1].lens).map(|lens| (index, lens))
            }) else {
                break;
            };
            let stages = groups[index].stages.start..groups[index + 1].stages.end;
            groups.splice(
                index..=index + 1,
                [NormalGroup {
                    stages,
                    lens: fused,
                }],
            );
        }
        groups
    }

    /// Deterministic table normal form for the leftmost-first fusion strategy.
    ///
    /// There must be one protocol for the source boundary, every shared
    /// boundary and the target boundary, in atomic-stage order.
    /// Starting with those atomic stages, this repeatedly fuses the leftmost
    /// adjacent pair admitted by table fusion at its three protocol
    /// boundaries. The result is a function of the stages and protocols, not
    /// a canonical form of table-lens behaviour, and it need not minimize the
    /// number of groups. The partial-put and product-complement interpretation
    /// is inferred from `xie2025effectful`, Sections 2.1 and 2.4.
    ///
    /// # Errors
    ///
    /// [`LensError::PathContextMismatch`] when the protocol count is not
    /// one more than the number of atomic stages.
    pub fn table_normal_form(&self, protocols: &[Protocol]) -> Result<Vec<NormalGroup>, LensError> {
        self.check_table_contexts(protocols)?;
        let mut groups: Vec<NormalGroup> = self
            .stages
            .iter()
            .enumerate()
            .map(|(index, lens)| NormalGroup {
                stages: index..index + 1,
                lens: duplicate(lens),
            })
            .collect();
        loop {
            let Some((index, fused)) = groups.windows(2).enumerate().find_map(|(index, pair)| {
                table_fusion(
                    &pair[0].lens,
                    &pair[1].lens,
                    &protocols[pair[0].stages.start],
                    &protocols[pair[0].stages.end],
                    &protocols[pair[1].stages.end],
                )
                .map(|lens| (index, lens))
            }) else {
                break;
            };
            let stages = groups[index].stages.start..groups[index + 1].stages.end;
            groups.splice(
                index..=index + 1,
                [NormalGroup {
                    stages,
                    lens: fused,
                }],
            );
        }
        Ok(groups)
    }

    /// Forward table-lens fold over table normal-form groups.
    ///
    /// # Errors
    ///
    /// A context-count mismatch or a located group error.
    pub fn get_table(
        &self,
        source: &FInstance,
        protocols: &[Protocol],
    ) -> Result<(FInstance, PathComplement<TableComplement>), LensError> {
        let groups = self.table_normal_form(protocols)?;
        let mut view = source.clone();
        let mut entries = Vec::with_capacity(groups.len());
        for (group_index, group) in groups.iter().enumerate() {
            let at = stage_index(group_index, group);
            let (next, complement) = if self.runs_fused(group, |schema| {
                table_source_declared(schema, &protocols[group.stages.start], &view)
            }) {
                let context = table_context(protocols, group);
                let (next, complement) = table_lens::get(&group.lens, &view, context)
                    .map_err(|error| locate(at, error))?;
                (next, GroupComplement::Fused(complement))
            } else {
                let mut next = view.clone();
                let mut complements = Vec::with_capacity(group.stages.len());
                for stage in group.stages.clone() {
                    let context = BoundaryProtocols {
                        src: &protocols[stage],
                        tgt: &protocols[stage + 1],
                    };
                    let (staged, complement) = table_lens::get(&self.stages[stage], &next, context)
                        .map_err(|error| locate(at.clone(), error))?;
                    complements.push(complement);
                    next = staged;
                }
                (next, GroupComplement::Sequential(complements))
            };
            entries.push(PathComplementEntry {
                complement,
                envelope: group.lens.identity(ComplementShape::Functor),
                stage_digests: self.digests_for(group.stages.clone(), ComplementShape::Functor),
            });
            view = next;
        }
        Ok((view, PathComplement::new(entries)))
    }

    /// Backward table-lens fold under the default identity policy.
    ///
    /// # Errors
    ///
    /// A context or complement-count mismatch, or a located group error.
    pub fn put_table(
        &self,
        view: &FInstance,
        complement: &PathComplement<TableComplement>,
        protocols: &[Protocol],
    ) -> Result<FInstance, LensError> {
        self.put_table_checked(view, complement, protocols, IdentityPolicy::AllowLegacy)
            .map(|(source, _)| source)
    }

    /// Backward table fold under an explicit identity policy.
    ///
    /// # Errors
    ///
    /// As [`Self::put_table`].
    pub fn put_table_checked(
        &self,
        view: &FInstance,
        complement: &PathComplement<TableComplement>,
        protocols: &[Protocol],
        policy: IdentityPolicy,
    ) -> Result<(FInstance, Vec<IdentityStatus>), LensError> {
        let groups = self.table_normal_form(protocols)?;
        check_entry_count(groups.len(), complement.len())?;
        let mut source = view.clone();
        let mut statuses = vec![IdentityStatus::Unbound; groups.len()];
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            self.check_table_entry(group, entry)
                .map_err(|error| locate(at.clone(), error))?;
            let (next, status) = match &entry.complement {
                GroupComplement::Fused(complement) => table_lens::put_checked(
                    &group.lens,
                    &source,
                    complement,
                    table_context(protocols, group),
                    policy,
                )
                .map_err(|error| locate(at, error))?,
                GroupComplement::Sequential(complements) => {
                    check_sequential_count(group, complements.len())
                        .map_err(|error| locate(at.clone(), error))?;
                    let mut staged = source.clone();
                    let mut group_statuses = Vec::with_capacity(complements.len());
                    for (stage, complement) in group.stages.clone().zip(complements).rev() {
                        let context = BoundaryProtocols {
                            src: &protocols[stage],
                            tgt: &protocols[stage + 1],
                        };
                        let (next, status) = table_lens::put_checked(
                            &self.stages[stage],
                            &staged,
                            complement,
                            context,
                            policy,
                        )
                        .map_err(|error| locate(at.clone(), error))?;
                        group_statuses.push(status);
                        staged = next;
                    }
                    group_statuses.reverse();
                    (staged, group_status(group_statuses))
                }
            };
            statuses[group_index] = status;
            source = next;
        }
        Ok((source, statuses))
    }

    /// Put-domain predicate for the table fold.
    ///
    /// The rightmost failing group whose right neighbours pass is reported.
    /// A context-count mismatch is outside this predicate and returns
    /// success; execution methods report it as [`LensError::PathContextMismatch`].
    ///
    /// # Errors
    ///
    /// The failing group and all of its ordered violations.
    pub fn check_table_put_domain(
        &self,
        view: &FInstance,
        complement: &PathComplement<TableComplement>,
        protocols: &[Protocol],
    ) -> Result<(), (StageIndex, Vec<PutDomainError>)> {
        let Ok(groups) = self.table_normal_form(protocols) else {
            return Ok(());
        };
        if groups.len() != complement.len() {
            return Ok(());
        }
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            let steps: Vec<(&Lens, &TableComplement, BoundaryProtocols<'_>)> =
                match &entry.complement {
                    GroupComplement::Fused(complement) => {
                        vec![(&group.lens, complement, table_context(protocols, group))]
                    }
                    GroupComplement::Sequential(complements) => {
                        if complements.len() != group.stages.len() {
                            return Ok(());
                        }
                        group
                            .stages
                            .clone()
                            .zip(complements)
                            .rev()
                            .map(|(stage, complement)| {
                                (
                                    &self.stages[stage],
                                    complement,
                                    BoundaryProtocols {
                                        src: &protocols[stage],
                                        tgt: &protocols[stage + 1],
                                    },
                                )
                            })
                            .collect()
                    }
                };
            for (lens, complement, context) in steps {
                if let Err(violations) =
                    table_lens::check_put_domain(lens, &source, complement, context)
                {
                    return Err((at, violations));
                }
                let mut for_domain = complement.clone();
                for_domain.stamp(lens.identity(ComplementShape::Functor), &lens.src_schema);
                match table_lens::put(lens, &source, &for_domain, context) {
                    Ok(next) => source = next,
                    Err(LensError::PutDomain(violation)) => return Err((at, vec![*violation])),
                    Err(_) => return Ok(()),
                }
            }
        }
        Ok(())
    }

    /// Reconstruct through every table group without a complement.
    ///
    /// # Errors
    ///
    /// A context mismatch or a located non-isomorphism or put error.
    pub fn put_table_without_complement(
        &self,
        view: &FInstance,
        protocols: &[Protocol],
    ) -> Result<FInstance, LensError> {
        let groups = self.table_normal_form(protocols)?;
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            source = table_lens::put_without_complement(
                &group.lens,
                &source,
                table_context(protocols, group),
            )
            .map_err(|error| locate(stage_index(group_index, group), error))?;
        }
        Ok(source)
    }

    /// Forward graph-lens fold over graph normal-form groups.
    ///
    /// # Errors
    ///
    /// A group error, located by its normal-form and atomic-stage indices.
    pub fn get_graph(
        &self,
        source: &GInstance,
    ) -> Result<(GInstance, PathComplement<GraphComplement>), LensError> {
        let groups = self.graph_normal_form();
        let mut view = source.clone();
        let mut entries = Vec::with_capacity(groups.len());
        for (group_index, group) in groups.iter().enumerate() {
            let at = stage_index(group_index, group);
            let (next, complement) =
                if self.runs_fused(group, |schema| graph_source_declared(schema, &view)) {
                    let (next, complement) =
                        graph_lens::get(&group.lens, &view).map_err(|error| locate(at, error))?;
                    (next, GroupComplement::Fused(complement))
                } else {
                    let mut next = view.clone();
                    let mut complements = Vec::with_capacity(group.stages.len());
                    for stage in group.stages.clone() {
                        let (staged, complement) = graph_lens::get(&self.stages[stage], &next)
                            .map_err(|error| locate(at.clone(), error))?;
                        complements.push(complement);
                        next = staged;
                    }
                    (next, GroupComplement::Sequential(complements))
                };
            entries.push(PathComplementEntry {
                complement,
                envelope: group.lens.identity(ComplementShape::Graph),
                stage_digests: self.digests_for(group.stages.clone(), ComplementShape::Graph),
            });
            view = next;
        }
        Ok((view, PathComplement::new(entries)))
    }

    /// Backward graph-lens fold over graph normal-form groups.
    ///
    /// # Errors
    ///
    /// A complement-count mismatch or a located group error.
    pub fn put_graph(
        &self,
        view: &GInstance,
        complement: &PathComplement<GraphComplement>,
    ) -> Result<GInstance, LensError> {
        self.put_graph_checked(view, complement, IdentityPolicy::AllowLegacy)
            .map(|(source, _)| source)
    }

    /// Backward graph fold under an explicit identity policy.
    ///
    /// # Errors
    ///
    /// As [`Self::put_graph`].
    pub fn put_graph_checked(
        &self,
        view: &GInstance,
        complement: &PathComplement<GraphComplement>,
        policy: IdentityPolicy,
    ) -> Result<(GInstance, Vec<IdentityStatus>), LensError> {
        let groups = self.graph_normal_form();
        check_entry_count(groups.len(), complement.len())?;
        let mut source = view.clone();
        let mut statuses = vec![IdentityStatus::Unbound; groups.len()];
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            self.check_graph_entry(group, entry)
                .map_err(|error| locate(at.clone(), error))?;
            let (next, status) = match &entry.complement {
                GroupComplement::Fused(complement) => {
                    graph_lens::put_checked(&group.lens, &source, complement, policy)
                        .map_err(|error| locate(at, error))?
                }
                GroupComplement::Sequential(complements) => {
                    check_sequential_count(group, complements.len())
                        .map_err(|error| locate(at.clone(), error))?;
                    let mut staged = source.clone();
                    let mut group_statuses = Vec::with_capacity(complements.len());
                    for (stage, complement) in group.stages.clone().zip(complements).rev() {
                        let (next, status) = graph_lens::put_checked(
                            &self.stages[stage],
                            &staged,
                            complement,
                            policy,
                        )
                        .map_err(|error| locate(at.clone(), error))?;
                        group_statuses.push(status);
                        staged = next;
                    }
                    group_statuses.reverse();
                    (staged, group_status(group_statuses))
                }
            };
            statuses[group_index] = status;
            source = next;
        }
        Ok((source, statuses))
    }

    /// Put-domain predicate for the graph fold.
    ///
    /// The rightmost failing group whose right neighbours pass is reported.
    ///
    /// # Errors
    ///
    /// The failing group and all of its ordered violations.
    pub fn check_graph_put_domain(
        &self,
        view: &GInstance,
        complement: &PathComplement<GraphComplement>,
    ) -> Result<(), (StageIndex, Vec<PutDomainError>)> {
        let groups = self.graph_normal_form();
        if groups.len() != complement.len() {
            return Ok(());
        }
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            let Some(steps) = self.group_steps(group, &entry.complement) else {
                return Ok(());
            };
            for (lens, complement) in steps {
                if let Err(violations) = graph_lens::check_put_domain(lens, &source, complement) {
                    return Err((at, violations));
                }
                let mut for_domain = complement.clone();
                for_domain.stamp(lens.identity(ComplementShape::Graph), &lens.src_schema);
                match graph_lens::put(lens, &source, &for_domain) {
                    Ok(next) => source = next,
                    Err(LensError::PutDomain(violation)) => return Err((at, vec![*violation])),
                    Err(_) => return Ok(()),
                }
            }
        }
        Ok(())
    }

    /// Reconstruct through every graph group without a complement.
    ///
    /// # Errors
    ///
    /// A located group is not an isomorphism or its graph put fails.
    pub fn put_graph_without_complement(&self, view: &GInstance) -> Result<GInstance, LensError> {
        let groups = self.graph_normal_form();
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            source = graph_lens::put_without_complement(&group.lens, &source)
                .map_err(|error| locate(stage_index(group_index, group), error))?;
        }
        Ok(source)
    }

    /// Forward tree-lens fold over this path's normal-form groups.
    ///
    /// # Errors
    ///
    /// A group error is wrapped in [`LensError::AtStage`].
    pub fn get(
        &self,
        source: &WInstance,
    ) -> Result<(WInstance, PathComplement<Complement>), LensError> {
        let groups = self.tree_normal_form();
        let mut view = source.clone();
        let mut entries = Vec::with_capacity(groups.len());
        for (group_index, group) in groups.iter().enumerate() {
            let at = stage_index(group_index, group);
            let (next, complement) =
                if self.runs_fused(group, |schema| tree_source_declared(schema, &view)) {
                    let (next, complement) = asymmetric::get(&group.lens, &view)
                        .map_err(|error| locate(at.clone(), error))?;
                    (next, GroupComplement::Fused(complement))
                } else {
                    let mut next = view.clone();
                    let mut complements = Vec::with_capacity(group.stages.len());
                    for stage in group.stages.clone() {
                        let (staged, complement) = asymmetric::get(&self.stages[stage], &next)
                            .map_err(|error| locate(at.clone(), error))?;
                        complements.push(complement);
                        next = staged;
                    }
                    (next, GroupComplement::Sequential(complements))
                };
            let envelope = group.lens.identity(ComplementShape::WType);
            entries.push(PathComplementEntry {
                complement,
                envelope,
                stage_digests: self.digests(group.stages.clone()),
            });
            view = next;
        }
        Ok((view, PathComplement::new(entries)))
    }

    /// Backward tree-lens fold over this path's normal-form groups.
    ///
    /// # Errors
    ///
    /// [`LensError::PathComplementMismatch`] for the wrong entry count;
    /// [`LensError::AtStage`] for a mismatched entry or a group put error.
    pub fn put(
        &self,
        view: &WInstance,
        complement: &PathComplement<Complement>,
    ) -> Result<WInstance, LensError> {
        self.put_checked(view, complement, IdentityPolicy::AllowLegacy)
            .map(|(source, _)| source)
    }

    /// Backward fold under an explicit identity policy, returning one
    /// status per normal-form group in forward group order.
    ///
    /// # Errors
    ///
    /// As [`LensPath::put`], with each complement checked under `policy`.
    pub fn put_checked(
        &self,
        view: &WInstance,
        complement: &PathComplement<Complement>,
        policy: IdentityPolicy,
    ) -> Result<(WInstance, Vec<IdentityStatus>), LensError> {
        let groups = self.tree_normal_form();
        check_entry_count(groups.len(), complement.len())?;
        let mut source = view.clone();
        let mut statuses = vec![IdentityStatus::Unbound; groups.len()];
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            self.check_entry(group, entry)
                .map_err(|error| locate(at.clone(), error))?;
            let (next, status) = match &entry.complement {
                GroupComplement::Fused(complement) => {
                    asymmetric::put_checked(&group.lens, &source, complement, policy)
                        .map_err(|error| locate(at, error))?
                }
                GroupComplement::Sequential(complements) => {
                    check_sequential_count(group, complements.len())
                        .map_err(|error| locate(at.clone(), error))?;
                    let mut staged = source.clone();
                    let mut group_statuses = Vec::with_capacity(complements.len());
                    for (stage, complement) in group.stages.clone().zip(complements).rev() {
                        let (next, status) = asymmetric::put_checked(
                            &self.stages[stage],
                            &staged,
                            complement,
                            policy,
                        )
                        .map_err(|error| locate(at.clone(), error))?;
                        group_statuses.push(status);
                        staged = next;
                    }
                    group_statuses.reverse();
                    (staged, group_status(group_statuses))
                }
            };
            statuses[group_index] = status;
            source = next;
        }
        Ok((source, statuses))
    }

    /// Domain predicate for the tree path's backward fold.
    ///
    /// The first failure is the rightmost failing group whose right
    /// neighbours all pass. Every violation from that group is returned;
    /// groups to its left are not inspected because the view they would put
    /// against does not yet exist.
    ///
    /// # Errors
    ///
    /// The failing group's location and its ordered put-domain report.
    pub fn check_put_domain(
        &self,
        view: &WInstance,
        complement: &PathComplement<Complement>,
    ) -> Result<(), (StageIndex, Vec<PutDomainError>)> {
        let groups = self.tree_normal_form();
        if groups.len() != complement.len() {
            return Ok(());
        }
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let entry = &complement.0[group_index];
            let at = stage_index(group_index, group);
            let Some(steps) = self.group_steps(group, &entry.complement) else {
                return Ok(());
            };
            for (lens, complement) in steps {
                if let Err(violations) = asymmetric::check_put_domain(lens, &source, complement) {
                    return Err((at, violations));
                }

                // Identity is not part of the put domain. Stamp a private
                // copy with the expected identity so the accepted step can
                // be run to produce the view for the step to its left.
                let mut for_domain = complement.clone();
                for_domain.stamp(lens.identity(ComplementShape::WType), &lens.src_schema);
                match asymmetric::put(lens, &source, &for_domain) {
                    Ok(next) => source = next,
                    Err(LensError::PutDomain(violation)) => return Err((at, vec![*violation])),
                    Err(_) => return Ok(()),
                }
            }
        }
        Ok(())
    }

    /// Reconstruct through every group without a complement.
    ///
    /// # Errors
    ///
    /// A group error is wrapped in [`LensError::AtStage`].
    pub fn put_without_complement(&self, view: &WInstance) -> Result<WInstance, LensError> {
        let groups = self.tree_normal_form();
        let mut source = view.clone();
        for group_index in (0..groups.len()).rev() {
            let group = &groups[group_index];
            let at = stage_index(group_index, group);
            source = asymmetric::put_without_complement(&group.lens, &source)
                .map_err(|error| locate(at, error))?;
        }
        Ok(source)
    }

    /// Consume this path as one tree-normal-form lens.
    ///
    /// # Errors
    ///
    /// [`LensError::NotSingleStage`] when the tree normal form has more
    /// than one group.
    pub fn into_single(self) -> Result<Lens, LensError> {
        let mut groups = self.tree_normal_form();
        if groups.len() != 1 {
            return Err(LensError::NotSingleStage {
                stages: groups.len(),
            });
        }
        Ok(groups.remove(0).lens)
    }

    /// Whether a group runs as its one lens: always for a one-stage group,
    /// and for a fused group exactly when `declared` holds of its source
    /// schema.
    fn runs_fused(&self, group: &NormalGroup, declared: impl FnOnce(&Schema) -> bool) -> bool {
        group.stages.len() == 1 || declared(&self.stages[group.stages.start].src_schema)
    }

    /// The lens and complement of each step of a group's put, in put order
    /// (right to left), or `None` for a sequential complement whose length
    /// is not the group's stage count.
    fn group_steps<'a, C>(
        &'a self,
        group: &'a NormalGroup,
        complement: &'a GroupComplement<C>,
    ) -> Option<Vec<(&'a Lens, &'a C)>> {
        match complement {
            GroupComplement::Fused(complement) => Some(vec![(&group.lens, complement)]),
            GroupComplement::Sequential(complements) => (complements.len() == group.stages.len())
                .then(|| {
                    group
                        .stages
                        .clone()
                        .zip(complements)
                        .rev()
                        .map(|(stage, complement)| (&self.stages[stage], complement))
                        .collect()
                }),
        }
    }

    fn duplicate(&self) -> Self {
        Self {
            stages: self.stages.iter().map(duplicate).collect(),
            distinguished_identity: self.distinguished_identity,
        }
    }

    fn digests(&self, stages: Range<usize>) -> Vec<Digest> {
        self.digests_for(stages, ComplementShape::WType)
    }

    fn digests_for(&self, stages: Range<usize>, shape: ComplementShape) -> Vec<Digest> {
        self.stages[stages]
            .iter()
            .map(|stage| stage.identity(shape).lens)
            .collect()
    }

    fn check_entry(
        &self,
        group: &NormalGroup,
        entry: &PathComplementEntry<Complement>,
    ) -> Result<(), LensError> {
        let expected_envelope = group.lens.identity(ComplementShape::WType);
        if let Some(error) = expected_envelope.mismatch(&entry.envelope) {
            return Err(error.into());
        }
        let expected_digests = self.digests(group.stages.clone());
        if expected_digests != entry.stage_digests {
            return Err(panproto_inst::IdentityError::Mismatch {
                field: IdentityField::Lens,
                expected: digest_list(&expected_digests),
                found: digest_list(&entry.stage_digests),
            }
            .into());
        }
        Ok(())
    }

    fn check_graph_entry(
        &self,
        group: &NormalGroup,
        entry: &PathComplementEntry<GraphComplement>,
    ) -> Result<(), LensError> {
        let expected_envelope = group.lens.identity(ComplementShape::Graph);
        if let Some(error) = expected_envelope.mismatch(&entry.envelope) {
            return Err(error.into());
        }
        let expected_digests = self.digests_for(group.stages.clone(), ComplementShape::Graph);
        if expected_digests != entry.stage_digests {
            return Err(panproto_inst::IdentityError::Mismatch {
                field: IdentityField::Lens,
                expected: digest_list(&expected_digests),
                found: digest_list(&entry.stage_digests),
            }
            .into());
        }
        Ok(())
    }

    fn check_table_entry(
        &self,
        group: &NormalGroup,
        entry: &PathComplementEntry<TableComplement>,
    ) -> Result<(), LensError> {
        let expected_envelope = group.lens.identity(ComplementShape::Functor);
        if let Some(error) = expected_envelope.mismatch(&entry.envelope) {
            return Err(error.into());
        }
        let expected_digests = self.digests_for(group.stages.clone(), ComplementShape::Functor);
        if expected_digests != entry.stage_digests {
            return Err(panproto_inst::IdentityError::Mismatch {
                field: IdentityField::Lens,
                expected: digest_list(&expected_digests),
                found: digest_list(&entry.stage_digests),
            }
            .into());
        }
        Ok(())
    }

    fn check_table_contexts(&self, protocols: &[Protocol]) -> Result<(), LensError> {
        let expected = self.stages.len() + 1;
        if protocols.len() == expected {
            Ok(())
        } else {
            Err(LensError::PathContextMismatch {
                expected,
                found: protocols.len(),
            })
        }
    }
}

/// Check that a sequential complement has one entry per atomic stage of
/// its group.
const fn check_sequential_count(group: &NormalGroup, found: usize) -> Result<(), LensError> {
    check_entry_count(group.stages.end - group.stages.start, found)
}

/// The identity status of a sequential group: the first stage status, in
/// forward order, that is not [`IdentityStatus::Verified`], or `Verified`
/// when every stage verified.
fn group_status(statuses: Vec<IdentityStatus>) -> IdentityStatus {
    statuses
        .into_iter()
        .find(|status| !matches!(status, IdentityStatus::Verified))
        .unwrap_or(IdentityStatus::Verified)
}

/// Whether every node anchor and edge label of `source` is declared by
/// `schema`, each edge joining nodes at its label's endpoints, with no
/// node of the fan shape.
fn graph_source_declared(schema: &Schema, source: &GInstance) -> bool {
    source.nodes().values().all(|node| {
        node.shape != panproto_inst::NodeShape::HyperEdge
            && schema.vertices.contains_key(&node.anchor)
    }) && source.edges_sorted().all(|(_, edge)| {
        schema.edges.contains_key(&edge.edge)
            && source
                .node(edge.src)
                .is_some_and(|node| node.anchor == edge.edge.src)
            && source
                .node(edge.tgt)
                .is_some_and(|node| node.anchor == edge.edge.tgt)
    })
}

/// Whether every node anchor and arc label of `source` is declared by
/// `schema`, each arc joining nodes at its label's endpoints, with no fan
/// and no node of the fan shape.
fn tree_source_declared(schema: &Schema, source: &WInstance) -> bool {
    source.fans.is_empty()
        && source.nodes.values().all(|node| {
            node.shape != panproto_inst::NodeShape::HyperEdge
                && schema.vertices.contains_key(&node.anchor)
        })
        && source.arcs.iter().all(|(parent, child, edge)| {
            schema.edges.contains_key(edge)
                && source
                    .nodes
                    .get(parent)
                    .is_some_and(|node| node.anchor == edge.src)
                && source
                    .nodes
                    .get(child)
                    .is_some_and(|node| node.anchor == edge.tgt)
        })
}

/// Whether every row of `source` lies in a table of `schema`'s relational
/// form under `protocol`, every cell in a column of its row's table, and
/// every foreign-key pair in a declared relation between rows of its
/// endpoint tables.
fn table_source_declared(schema: &Schema, protocol: &Protocol, source: &FInstance) -> bool {
    let Ok(relational) = panproto_inst::RelSchema::new(schema, protocol) else {
        return false;
    };
    source.tables().into_iter().all(|(table, rows)| {
        relational.is_table(table)
            && schema.vertices.contains_key(table)
            && rows.rows().into_iter().all(|(_, row)| {
                let columns = relational.columns(table);
                row.keys().all(|column| columns.contains_key(column))
            })
    }) && source.foreign_keys().into_iter().all(|(edge, pairs)| {
        relational.is_relation(edge)
            && pairs.iter().all(|(src, tgt)| {
                source.table_of(*src) == Some(&edge.src) && source.table_of(*tgt) == Some(&edge.tgt)
            })
    })
}

const fn check_entry_count(expected: usize, found: usize) -> Result<(), LensError> {
    if expected == found {
        Ok(())
    } else {
        Err(LensError::PathComplementMismatch { expected, found })
    }
}

fn stage_index(group: usize, normal: &NormalGroup) -> StageIndex {
    StageIndex {
        group,
        stages: normal.stages.clone(),
    }
}

const fn table_context<'a>(
    protocols: &'a [Protocol],
    group: &NormalGroup,
) -> BoundaryProtocols<'a> {
    BoundaryProtocols {
        src: &protocols[group.stages.start],
        tgt: &protocols[group.stages.end],
    }
}

fn locate(at: StageIndex, error: LensError) -> LensError {
    let error = match error {
        LensError::AtStage { error, .. } => error,
        other => Box::new(other),
    };
    LensError::AtStage { at, error }
}

fn digest_list(digests: &[Digest]) -> String {
    digests
        .iter()
        .map(Digest::to_hex)
        .collect::<Vec<_>>()
        .join(",")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tests::{identity_lens, projection_lens, three_node_instance, three_node_schema};
    use panproto_inst::{FieldTransform, ViewRef};

    fn path_digests(path: &LensPath) -> Vec<String> {
        path.identity_envelope(ComplementShape::WType)
            .into_iter()
            .map(|envelope| envelope.lens.to_hex())
            .collect()
    }

    fn normal_form_signature(path: &LensPath) -> Vec<(Range<usize>, String)> {
        path.tree_normal_form()
            .into_iter()
            .map(|group| {
                (
                    group.stages,
                    group.lens.identity(ComplementShape::WType).lens.to_hex(),
                )
            })
            .collect()
    }

    #[test]
    fn lens_path_unit_laws() {
        let schema = three_node_schema();
        let path = LensPath::single(projection_lens(&schema, "createdAt"));
        let source_identity = LensPath::identity(path.src_schema());
        let target_identity = LensPath::identity(path.tgt_schema());

        let left = source_identity
            .then(&path)
            .unwrap_or_else(|error| panic!("left unit failed: {error}"));
        let right = path
            .then(&target_identity)
            .unwrap_or_else(|error| panic!("right unit failed: {error}"));
        assert_eq!(left.len(), path.len());
        assert_eq!(right.len(), path.len());
        assert_eq!(path_digests(&left), path_digests(&path));
        assert_eq!(path_digests(&right), path_digests(&path));
        assert_eq!(
            left.identity_envelope(ComplementShape::WType),
            path.identity_envelope(ComplementShape::WType)
        );
        assert_eq!(
            right.identity_envelope(ComplementShape::WType),
            path.identity_envelope(ComplementShape::WType)
        );
    }

    #[test]
    fn lens_path_normal_form_is_a_function_of_the_atomic_stages() {
        let schema = three_node_schema();
        let p = LensPath::single(identity_lens(&schema));
        let q = LensPath::single(identity_lens(&schema));
        let r = LensPath::single(identity_lens(&schema));

        let left = p
            .then(&q)
            .unwrap_or_else(|error| panic!("first left association failed: {error}"))
            .then(&r)
            .unwrap_or_else(|error| panic!("second left association failed: {error}"));
        let qr = q
            .then(&r)
            .unwrap_or_else(|error| panic!("inner right association failed: {error}"));
        let right = p
            .then(&qr)
            .unwrap_or_else(|error| panic!("outer right association failed: {error}"));

        assert_eq!(left.len(), 3);
        assert_eq!(path_digests(&left), path_digests(&right));
        assert_eq!(normal_form_signature(&left), normal_form_signature(&right));

        let groups = left.tree_normal_form();
        assert!(
            groups.windows(2).all(|pair| {
                crate::compose::tree_fusion(&pair[0].lens, &pair[1].lens).is_none()
            })
        );
    }

    #[test]
    fn a_single_identity_lens_is_not_the_distinguished_identity() {
        let schema = three_node_schema();
        assert!(!LensPath::single(identity_lens(&schema)).is_identity());
        assert!(LensPath::identity(&schema).is_identity());
    }

    #[test]
    fn a_tree_lens_path_round_trips() {
        let schema = three_node_schema();
        let path = LensPath::single(identity_lens(&schema));
        let source = three_node_instance();
        let (view, complement) = path
            .get(&source)
            .unwrap_or_else(|error| panic!("path get failed: {error}"));
        let restored = path
            .put(&view, &complement)
            .unwrap_or_else(|error| panic!("path put failed: {error}"));
        assert!(crate::laws::instances_equivalent(&restored, &source));
    }

    #[test]
    fn path_put_checks_the_group_count_and_atomic_digests() {
        let schema = three_node_schema();
        let path = LensPath::single(identity_lens(&schema));
        let source = three_node_instance();
        let (view, complement) = path
            .get(&source)
            .unwrap_or_else(|error| panic!("path get failed: {error}"));

        assert!(matches!(
            path.put(&view, &PathComplement::new(Vec::new())),
            Err(LensError::PathComplementMismatch {
                expected: 1,
                found: 0
            })
        ));

        let mut entries = complement.entries().to_vec();
        entries[0].stage_digests.clear();
        let Err(error) = path.put(&view, &PathComplement::new(entries)) else {
            panic!("put accepted a complement with no stage digests");
        };
        assert!(matches!(
            error,
            LensError::AtStage {
                at: StageIndex {
                    group: 0,
                    stages
                },
                error
            } if stages == (0..1) && matches!(*error, LensError::Identity(_))
        ));
    }

    #[test]
    fn path_check_put_domain_reports_the_first_failing_group_in_put_order() {
        let schema = three_node_schema();
        let mut first = identity_lens(&schema);
        first.compiled.field_transforms.insert(
            "post:body".into(),
            vec![FieldTransform::DropField {
                key: "absent-first".to_owned(),
            }],
        );
        let mut second = identity_lens(&schema);
        second.compiled.field_transforms.insert(
            "post:body".into(),
            vec![FieldTransform::DropField {
                key: "absent-second".to_owned(),
            }],
        );
        let path = LensPath::single(first)
            .then(&LensPath::single(second))
            .unwrap_or_else(|error| panic!("path construction failed: {error}"));
        let groups = path.tree_normal_form();
        assert_eq!(groups.len(), 2);

        let source = three_node_instance();
        let (view, mut complement) = path
            .get(&source)
            .unwrap_or_else(|error| panic!("path get failed: {error}"));
        for (group, entry) in groups.iter().zip(&mut complement.0) {
            let GroupComplement::Fused(group_complement) = &mut entry.complement else {
                panic!("a one-stage group records its one complement");
            };
            group_complement
                .dropped_nodes
                .insert(0, source.nodes[&0].clone());
            assert!(matches!(
                asymmetric::check_put_domain(&group.lens, &view, group_complement),
                Err(violations)
                    if matches!(violations.as_slice(), [PutDomainError::IdCollision {
                        elem: ViewRef::Node(0)
                    }])
            ));
        }

        assert!(matches!(
            path.check_put_domain(&view, &complement),
            Err((
                StageIndex {
                    group: 1,
                    stages
                },
                violations
            )) if stages == (1..2)
                && matches!(violations.as_slice(), [PutDomainError::IdCollision {
                    elem: ViewRef::Node(0)
                }])
        ));
    }

    /// An edge label `three_node_schema` does not declare.
    fn undeclared_label(tgt: &str) -> panproto_schema::Edge {
        panproto_schema::Edge {
            src: "post:body".into(),
            tgt: tgt.into(),
            kind: "prop".into(),
            name: Some("undeclared".into()),
        }
    }

    /// The unlocated error inside a path or stage refusal.
    fn unlocated(error: &LensError) -> String {
        match error {
            LensError::AtStage { error, .. } => format!("{error:?}"),
            other => format!("{other:?}"),
        }
    }

    /// The atomic graph fold: get left to right, keeping each stage's
    /// complement, then put `edited` right to left.
    fn atomic_graph_fold(
        stages: &[Lens],
        source: &GInstance,
        edited: impl FnOnce(&GInstance) -> GInstance,
    ) -> (Result<GInstance, String>, Option<Result<GInstance, String>>) {
        let mut view = source.clone();
        let mut complements = Vec::new();
        for stage in stages {
            match graph_lens::get(stage, &view) {
                Ok((next, complement)) => {
                    complements.push(complement);
                    view = next;
                }
                Err(error) => return (Err(unlocated(&error)), None),
            }
        }
        let mut restored = edited(&view);
        for (stage, complement) in stages.iter().zip(&complements).rev() {
            match graph_lens::put(stage, &restored, complement) {
                Ok(next) => restored = next,
                Err(error) => return (Ok(view), Some(Err(unlocated(&error)))),
            }
        }
        (Ok(view), Some(Ok(restored)))
    }

    /// The normal-form graph fold of `path`, in the shape of
    /// [`atomic_graph_fold`].
    fn normal_graph_fold(
        path: &LensPath,
        source: &GInstance,
        edited: impl FnOnce(&GInstance) -> GInstance,
    ) -> (Result<GInstance, String>, Option<Result<GInstance, String>>) {
        match path.get_graph(source) {
            Err(error) => (Err(unlocated(&error)), None),
            Ok((view, complement)) => {
                let put = path
                    .put_graph(&edited(&view), &complement)
                    .map_err(|error| unlocated(&error));
                (Ok(view), Some(put))
            }
        }
    }

    #[test]
    fn a_fused_identity_pair_keeps_put_precedence_on_an_undeclared_anchor() {
        let schema = three_node_schema();
        let stages = [identity_lens(&schema), identity_lens(&schema)];
        let path = LensPath::single(identity_lens(&schema))
            .then(&LensPath::single(identity_lens(&schema)))
            .unwrap_or_else(|error| panic!("path construction failed: {error}"));
        assert_eq!(path.graph_normal_form().len(), 1, "the pair fuses");
        let source = GInstance::new()
            .with_node(panproto_inst::Node::new(0, "post:body"))
            .with_node(panproto_inst::Node::new(1, "undeclared"));
        // Reuse the dropped node's id at a declared anchor and attach it by
        // an undeclared label, so the second stage alone refuses the label
        // while the first alone would refuse the reused id.
        let edit = |view: &GInstance| {
            let mut edited = view.clone();
            edited
                .insert_node(panproto_inst::Node::new(1, "post:body"))
                .unwrap_or_else(|error| panic!("fresh node: {error}"));
            edited
                .insert_edge(
                    panproto_inst::EdgeId(0),
                    panproto_inst::GEdge::new(0, 1, undeclared_label("post:body")),
                )
                .unwrap_or_else(|error| panic!("fresh edge: {error}"));
            edited
        };
        let atomic = atomic_graph_fold(&stages, &source, edit);
        let normal = normal_graph_fold(&path, &source, edit);
        assert!(matches!(atomic.1, Some(Err(_))), "the atomic put refuses");
        assert_eq!(normal, atomic);
    }

    #[test]
    fn a_fused_predicate_pair_keeps_the_get_refusal_on_an_undeclared_label() {
        let schema = three_node_schema();
        let mut predicate = identity_lens(&schema);
        predicate
            .compiled
            .conditional_survival
            .insert("post:body".into(), panproto_expr::Expr::var("x"));
        let stages = [identity_lens(&schema), duplicate(&predicate)];
        let path = LensPath::single(identity_lens(&schema))
            .then(&LensPath::single(predicate))
            .unwrap_or_else(|error| panic!("path construction failed: {error}"));
        assert_eq!(path.graph_normal_form().len(), 1, "the pair fuses");
        let mut hidden = panproto_inst::Node::new(0, "post:body");
        hidden
            .extra_fields
            .insert("x".into(), panproto_inst::Value::Bool(false));
        let mut kept = panproto_inst::Node::new(1, "post:body");
        kept.extra_fields
            .insert("x".into(), panproto_inst::Value::Bool(true));
        let mut source = GInstance::new().with_node(hidden).with_node(kept);
        source
            .insert_edge(
                panproto_inst::EdgeId(0),
                panproto_inst::GEdge::new(0, 1, undeclared_label("post:body")),
            )
            .unwrap_or_else(|error| panic!("source edge: {error}"));
        let atomic = atomic_graph_fold(&stages, &source, Clone::clone);
        let normal = normal_graph_fold(&path, &source, Clone::clone);
        assert!(atomic.0.is_err(), "the atomic get refuses");
        assert_eq!(normal, atomic);
    }

    #[test]
    fn a_fused_tree_identity_pair_keeps_put_precedence_on_an_undeclared_anchor() {
        let schema = three_node_schema();
        let stages = [identity_lens(&schema), identity_lens(&schema)];
        let path = LensPath::single(identity_lens(&schema))
            .then(&LensPath::single(identity_lens(&schema)))
            .unwrap_or_else(|error| panic!("path construction failed: {error}"));
        assert_eq!(path.tree_normal_form().len(), 1, "the pair fuses");
        let mut source = three_node_instance();
        source
            .nodes
            .insert(9, panproto_inst::Node::new(9, "undeclared"));
        source.arcs.push((0, 9, undeclared_label("undeclared")));
        let source = WInstance::new(
            source.nodes,
            source.arcs,
            source.fans,
            source.root,
            source.schema_root,
        );
        let edit = |view: &WInstance| {
            let mut nodes = view.nodes.clone();
            nodes.insert(9, panproto_inst::Node::new(9, "post:body.text"));
            let mut arcs = view.arcs.clone();
            arcs.push((0, 9, undeclared_label("post:body.text")));
            WInstance::new(
                nodes,
                arcs,
                view.fans.clone(),
                view.root,
                view.schema_root.clone(),
            )
        };
        let atomic = {
            let mut view = source.clone();
            let mut complements = Vec::new();
            let mut refusal = None;
            for stage in &stages {
                match asymmetric::get(stage, &view) {
                    Ok((next, complement)) => {
                        complements.push(complement);
                        view = next;
                    }
                    Err(error) => {
                        refusal = Some(unlocated(&error));
                        break;
                    }
                }
            }
            refusal.map_or_else(
                || {
                    let mut restored = edit(&view);
                    let mut put = None;
                    for (stage, complement) in stages.iter().zip(&complements).rev() {
                        match asymmetric::put(stage, &restored, complement) {
                            Ok(next) => restored = next,
                            Err(error) => {
                                put = Some(Err(unlocated(&error)));
                                break;
                            }
                        }
                    }
                    (Ok(view), Some(put.unwrap_or(Ok(restored))))
                },
                |error| (Err(error), None),
            )
        };
        let normal = match path.get(&source) {
            Err(error) => (Err(unlocated(&error)), None),
            Ok((view, complement)) => {
                let put = path
                    .put(&edit(&view), &complement)
                    .map_err(|error| unlocated(&error));
                (Ok(view), Some(put))
            }
        };
        let same = match (&atomic, &normal) {
            ((Ok(a), Some(Ok(ra))), (Ok(b), Some(Ok(rb)))) => {
                crate::laws::instances_equivalent(a, b) && crate::laws::instances_equivalent(ra, rb)
            }
            ((Ok(a), Some(Err(ea))), (Ok(b), Some(Err(eb)))) => {
                crate::laws::instances_equivalent(a, b) && ea == eb
            }
            ((Err(ea), None), (Err(eb), None)) => ea == eb,
            _ => false,
        };
        assert!(same, "atomic {atomic:?} against normal {normal:?}");
    }

    #[test]
    fn into_single_refuses_a_path_of_two_groups() {
        let schema = three_node_schema();
        let first = projection_lens(&schema, "createdAt");
        let middle = first.tgt_schema.clone();
        let second = identity_lens(&middle);
        let path = LensPath::single(first)
            .then(&LensPath::single(second))
            .unwrap_or_else(|error| panic!("path construction failed: {error}"));
        let groups = path.tree_normal_form().len();
        let result = path.into_single();
        if groups == 1 {
            assert!(result.is_ok());
        } else {
            assert!(matches!(
                result,
                Err(LensError::NotSingleStage { stages }) if stages == groups
            ));
        }
    }
}
